type Tab =
  | "map"
  | "stratmap"
  | "squad"
  | "pl"
  | "builder"
  | "spec"
  | "merits"
  | "saves"
  | "settings";
type CompanySetting = Squad | "None";
type CertSubTab = "checklist" | "rules" | "training";
type SaveScannerCompanyTab = "All" | Squad;

type SaveScannerTypeTab =
  | "All"
  | "Squad"
  | "PL"
  | "Builder"
  | "Specialisation"
  | "Merits & Awards";
type Squad = "Demon" | "Nightmare" | "Cerberus" | "Hellfire";
type Status = "" | "yes" | "no" | "na";
type MarkerType =
  | "destroyed"
  | "noSpawn"
  | "ore"
  | "gas"
  | "base"
  | "archnigeon"
  | "hive"
  | "exterms"
  | "trooper"
  | "teardown"
  | "bombardment"
  | "scorpion"
  | "tanker"
  | "fleetRelay"
  | "sideObjective"
  | "nightmareIncorporated"
  | "cerberusDogHouse"
  | "hellfireHotel";
type Item = { id: string; text: string; points: number };
type Section = { id: number; title: string; items: Item[] };
type Cert = { title: string; fields: string[]; pass: number; total: number; fails: string[]; sections: Section[]; notes?: string[] };
type CertState = { info: Record<string, string>; scores: Record<string, Status>; fails: Record<string, boolean>; notes: string };
type Marker = { id: string; type: MarkerType; x: number; y: number; map: string };
type SquadState = { orders: string; ore: number; gas: number; checks: Record<string, boolean> };
type SpecDef = { passScore: number; totalPoints: number; sections: Array<{ title: string; items: string[] }>; instantFails: string[] };
type OverlayApiWindow = Window & {
  steOverlay?: {
    open: () => Promise<void>;
    close: () => Promise<void>;
    setClickThrough: (enabled: boolean) => Promise<void>;
    toggleClickThrough?: () => Promise<void>;
    onClosed?: (callback: () => void) => () => void;
  };
};

type KeybindSettings = {
  overlay: string;
  bugHoles: string;
  mapLayers: string;
};

type KeybindApiWindow = Window & {
  steKeybinds?: {
    get: () => Promise<KeybindSettings>;
    set: (keybinds: KeybindSettings) => Promise<KeybindSettings>;
    onToggleBugHoles: (callback: () => void) => () => void;
    onToggleMapLayers: (callback: () => void) => () => void;
  };
};

const appAsset = (path: string) => {
  const cleanPath = path.replace(/^\/+/, "");
  const basePath = window.location.href.split("#")[0];

  return new URL(cleanPath, basePath).toString();
};

