const makeItems = (
    prefix: string,
    sec: number,
    texts: string[],
    points?: number[]
    ): Item[] =>
    texts.map((text, i) => ({
      id: `${prefix}-${sec}-${i + 1}`,
      text,
      points: points?.[i] ?? 1
  }));

const generated = (
    prefix: string,
    sec: number,
    count: number,
    label: string
  ) =>
  makeItems(
    prefix,
    sec,
    Array.from({ length: count }, (_, i) => `${label} task ${i + 1}.`)
  );

const makeSection = (id: number, title: string, items: Item[]): Section => ({
    id,
    title,
    items
});

