const CERT_SUBTAB_CHANNEL_NAME = "ste-cert-subtab-channel";

const CERT_STATE_SAVE_PREFIX = "ste-cert-state-";
const CERT_STATE_CHANNEL_NAME = "ste-cert-state-channel";

type CertStateSyncMessage = {
  sourceId: string;
  certId: "squad" | "pl" | "builder";
  state: CertState;
};

const getCertStateKey = (certId: "squad" | "pl" | "builder") => {
  return CERT_STATE_SAVE_PREFIX + certId;
};

const getSavedCertState = (certId: "squad" | "pl" | "builder") => {
  try {
    const saved = localStorage.getItem(getCertStateKey(certId));
    if (!saved) return null;

    const parsed = JSON.parse(saved) as CertState;

    return withLockedTrainerName({
      info: parsed.info || {},
      scores: parsed.scores || {},
      fails: parsed.fails || {},
      notes: parsed.notes || ""
    });
  } catch {
    return null;
  }
};

const saveCertStateSync = (
  certId: "squad" | "pl" | "builder",
  state: CertState
) => {
  const cleanState = withLockedTrainerName(state);

  localStorage.setItem(
    getCertStateKey(certId),
    JSON.stringify(cleanState)
  );

  window.dispatchEvent(
    new CustomEvent("ste-cert-state-updated", {
      detail: {
        certId,
        state: cleanState
      }
    })
  );

  try {
    const channel = new BroadcastChannel(CERT_STATE_CHANNEL_NAME);

    channel.postMessage({
      sourceId: APP_WINDOW_SYNC_ID,
      certId,
      state: cleanState
    } as CertStateSyncMessage);

    channel.close();
  } catch {
    // BroadcastChannel may not be available in some Electron contexts.
  }
};

