const SHARED_MODIFIERS_SAVE_KEY = "ste-shared-modifiers";
const SHARED_MODIFIERS_CHANNEL_NAME = "ste-shared-modifiers-channel";

type SharedModifiersSyncMessage = {
  sourceId: string;
  modifiers: string[];
};

const APP_WINDOW_SYNC_ID =
  Date.now().toString() + "-" + Math.random().toString(36).slice(2);

type AppTabSyncMessage = {
  sourceId: string;
  tab: Tab;
};

type CertSubTabSyncMessage = {
  sourceId: string;
  certId: string;
  subTab: CertSubTab;
};

const isValidTab = (value: string): value is Tab => {
  return tabs.some((item) => item.id === value);
};

const isValidCertSubTab = (value: string): value is CertSubTab => {
  return value === "checklist" || value === "rules";
};

const normaliseSharedModifiers = (value: string | string[]) => {
  const list = Array.isArray(value)
    ? value
    : parseMutators(value);

  return list.filter((item, index, array) => {
    return modifiers.includes(item) && array.indexOf(item) === index;
  });
};

const getSharedModifiers = () => {
  try {
    const saved = localStorage.getItem(SHARED_MODIFIERS_SAVE_KEY);

    if (!saved) return [];

    const parsed = JSON.parse(saved);

    return normaliseSharedModifiers(parsed);
  } catch {
    return [];
  }
};

const saveSharedModifiers = (nextModifiers: string[]) => {
  const cleaned = normaliseSharedModifiers(nextModifiers);

  localStorage.setItem(
    SHARED_MODIFIERS_SAVE_KEY,
    JSON.stringify(cleaned)
  );

  window.dispatchEvent(
    new CustomEvent("ste-shared-modifiers-updated", {
      detail: cleaned
    })
  );

  try {
    const channel = new BroadcastChannel(SHARED_MODIFIERS_CHANNEL_NAME);

    channel.postMessage({
      sourceId: APP_WINDOW_SYNC_ID,
      modifiers: cleaned
    } as SharedModifiersSyncMessage);

    channel.close();
  } catch {
    // BroadcastChannel may not be available in some Electron contexts.
  }
};

