function BuilderStepPopup(props: { onClose: () => void }) {
  const [pageIndex, setPageIndex] = useState(0);

  const page = builderStepPages[pageIndex];

  const previousPage = () => {
    setPageIndex((old) =>
      old === 0 ? builderStepPages.length - 1 : old - 1
    );
  };

  const nextPage = () => {
    setPageIndex((old) =>
      old === builderStepPages.length - 1 ? 0 : old + 1
    );
  };

  return (
    <div className="modal-backdrop">
      <div className="modal-card builder-step-popup">
        <div className="modal-header">
          <h2>{page.title}</h2>

          <button
            type="button"
            className="modal-close"
            onClick={props.onClose}
          >
            ×
          </button>
        </div>

        <div className="builder-step-page-count">
          Page {pageIndex + 1} of {builderStepPages.length}
        </div>

        {page.images.length > 0 ? (
          <div className="builder-step-images">
            {page.images.map((imagePath) => (
              <img
                key={imagePath}
                src={appAsset(imagePath)}
                alt={page.title}
                className="builder-step-image"
              />
            ))}
          </div>
        ) : null}

        <Card>
          {page.items.map((item) => (
            <label key={item} className="row">
              <span>•</span>
              {item}
            </label>
          ))}
        </Card>

        <div className="builder-step-actions">
          <Button onClick={previousPage}>← Previous</Button>
          <Button onClick={nextPage}>Next →</Button>
        </div>
      </div>
    </div>
  );
}

