function MiStratmapPanel() {
  const [selectedMap, setSelectedMap] = useState("Valaka Plateau");
  const [boreasLevel, setBoreasLevel] = useState("Plateau");
  const [showBugHoles, setShowBugHoles] = useState(false);
  const [toolMode, setToolMode] = useState<"structures" | "markers">("structures");
  const [selectedStructure, setSelectedStructure] = useState<StratStructureType>("wall");
  const [selectedMarker, setSelectedMarker] = useState<MarkerType>("base");
  const [items, setItems] = useState<StratPlacedItem[]>([]);
  const [selectedItemId, setSelectedItemId] = useState("");
  const [notes, setNotes] = useState("");
  const [zoom, setZoom] = useState(1);

  const activeMapKey =
    selectedMap === "Boreas" ? "Boreas " + boreasLevel : selectedMap;

  const activeMapPath = activeMapKey
    ? mapAssetPaths[activeMapKey] || mapAssetPaths[selectedMap]
    : "";

  const activeBugHolePath = activeMapKey
    ? bugHoleMapPaths[activeMapKey] || bugHoleMapPaths[selectedMap]
    : "";

  const selectedItem = items.find((item) => item.id === selectedItemId);

  const selectedStructureInfo = stratStructures.find(
    (structure) => structure.id === selectedStructure
  );

  const selectedMarkerInfo = markerTypes.find(
    (marker) => marker.id === selectedMarker
  );

  const placeItem = (event: React.MouseEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();

    const x = ((event.clientX - rect.left) / rect.width) * 100;
    const y = ((event.clientY - rect.top) / rect.height) * 100;

    const nextItem: StratPlacedItem = {
      id: Date.now().toString() + "-" + Math.random().toString(36).slice(2),
      kind: toolMode === "structures" ? "structure" : "marker",
      structureType: toolMode === "structures" ? selectedStructure : undefined,
      markerType: toolMode === "markers" ? selectedMarker : undefined,
      x,
      y,
      rotation: 0
    };

    setItems((old) => [...old, nextItem]);
    setSelectedItemId(nextItem.id);
  };

  const rotateSelected = () => {
    if (!selectedItemId) return;

    setItems((old) =>
      old.map((item) =>
        item.id === selectedItemId
          ? { ...item, rotation: (item.rotation + 45) % 360 }
          : item
      )
    );
  };

  const deleteSelected = () => {
    if (!selectedItemId) return;

    setItems((old) => old.filter((item) => item.id !== selectedItemId));
    setSelectedItemId("");
  };

  const clearPlan = () => {
    if (!confirm("Clear the current M.I. STRATMAP plan?")) return;

    setItems([]);
    setSelectedItemId("");
    setNotes("");
  };

  const exportPlan = () => {
    exportJson("MI-STRATMAP-Plan.json", {
      saveType: "mi-stratmap-plan",
      mapName: selectedMap,
      activeMapKey,
      boreasLevel,
      showBugHoles,
      items,
      notes,
      savedAt: new Date().toISOString()
    });
  };

  const structureCounts = stratStructures.map((structure) => ({
    ...structure,
    count: items.filter(
      (item) => item.kind === "structure" && item.structureType === structure.id
    ).length
  }));

  return (
    <div className="stratmap-shell">
      <div className="stratmap-topbar">
        <div>
          <h2>M.I. STRATMAP</h2>
          <p>Blueprint planner for bases, markers, bug holes, and operation layouts.</p>
        </div>

        <div className="stratmap-top-controls">
          <label>
            Map
            <MapDropdown value={selectedMap} onChange={setSelectedMap} />
          </label>

          {selectedMap === "Boreas" ? (
            <label>
              Layer
              <select
                value={boreasLevel}
                onChange={(event) => setBoreasLevel(event.target.value)}
              >
                {boreasLevels.map((level) => (
                  <option key={level} value={level}>
                    {level}
                  </option>
                ))}
              </select>
            </label>
          ) : null}

          <Button active={showBugHoles} onClick={() => setShowBugHoles((old) => !old)}>
            Bug Holes
          </Button>

          <Button onClick={() => setZoom((old) => Math.min(old + 0.15, 2.5))}>
            +
          </Button>

          <Button onClick={() => setZoom((old) => Math.max(old - 0.15, 0.6))}>
            -
          </Button>

          <Button onClick={() => setZoom(1)}>Reset View</Button>
          <Button onClick={exportPlan}>Export</Button>
          <Button onClick={clearPlan}>Clear</Button>
        </div>
      </div>

      <div className="stratmap-body">
        <aside className="stratmap-left">
          <Card>
            <h3>Tools</h3>

            <div className="stratmap-mode-buttons">
              <Button
                active={toolMode === "structures"}
                onClick={() => setToolMode("structures")}
              >
                Structures
              </Button>

              <Button
                active={toolMode === "markers"}
                onClick={() => setToolMode("markers")}
              >
                Markers
              </Button>
            </div>

            {toolMode === "structures" ? (
              <div className="stratmap-tool-grid">
                {stratStructures.map((structure) => (
                  <button
                    key={structure.id}
                    type="button"
                    className={
                      "stratmap-tool " +
                      (selectedStructure === structure.id ? "active" : "")
                    }
                    onClick={() => setSelectedStructure(structure.id)}
                  >
                    <span
                      className="stratmap-tool-colour"
                      style={{ backgroundColor: structure.colour }}
                    />
                    {structure.label}
                  </button>
                ))}
              </div>
            ) : (
              <div className="stratmap-tool-grid">
                {markerTypes.map((marker) => (
                  <button
                    key={marker.id}
                    type="button"
                    className={
                      "stratmap-tool " +
                      (selectedMarker === marker.id ? "active" : "")
                    }
                    onClick={() => setSelectedMarker(marker.id)}
                  >
                    <span
                      className="stratmap-tool-colour"
                      style={{ backgroundColor: marker.color }}
                    />
                    {marker.label}
                  </button>
                ))}
              </div>
            )}
          </Card>

          <Card>
            <h3>Selected Item</h3>

            {selectedItem ? (
              <>
                <p>
                  <b>
                    {selectedItem.kind === "structure"
                      ? stratStructures.find(
                          (structure) => structure.id === selectedItem.structureType
                        )?.label
                      : markerTypes.find(
                          (marker) => marker.id === selectedItem.markerType
                        )?.label}
                  </b>
                </p>

                <p>Rotation: {selectedItem.rotation}°</p>

                <div className="grid-two">
                  <Button onClick={rotateSelected}>Rotate</Button>
                  <Button onClick={deleteSelected}>Delete</Button>
                </div>
              </>
            ) : (
              <p className="stratmap-muted">Click a placed item to edit it.</p>
            )}
          </Card>

          <Card>
            <h3>Report</h3>

            <div className="stratmap-report">
              <div>
                <span>Map</span>
                <b>{activeMapKey || "None"}</b>
              </div>

              <div>
                <span>Tool</span>
                <b>
                  {toolMode === "structures"
                    ? selectedStructureInfo?.label
                    : selectedMarkerInfo?.label}
                </b>
              </div>

              <div>
                <span>Total Items</span>
                <b>{items.length}</b>
              </div>

              <div>
                <span>Zoom</span>
                <b>{Math.round(zoom * 100)}%</b>
              </div>
            </div>
          </Card>
        </aside>

        <main className="stratmap-main">
          <div className="stratmap-map-header">
            <strong>{activeMapKey || "No Map Selected"}</strong>
            <span>
              Click map to place:{" "}
              {toolMode === "structures"
                ? selectedStructureInfo?.label
                : selectedMarkerInfo?.label}
            </span>
          </div>

          <div className="stratmap-map-frame">
            <div
              className="stratmap-map-stage"
              style={{ transform: `scale(${zoom})` }}
              onClick={placeItem}
            >
              {activeMapPath ? (
                <img
                  className="stratmap-map-image"
                  src={appAsset(activeMapPath)}
                  alt={activeMapKey}
                  draggable={false}
                />
              ) : (
                <div className="stratmap-empty">No map selected</div>
              )}

              {showBugHoles && activeBugHolePath ? (
                <img
                  className="stratmap-bughole-image"
                  src={appAsset(activeBugHolePath)}
                  alt={`${activeMapKey} bug holes`}
                  draggable={false}
                />
              ) : null}

              {items.map((item) => {
                const structure = item.structureType
                  ? stratStructures.find((entry) => entry.id === item.structureType)
                  : null;

                const marker = item.markerType
                  ? markerTypes.find((entry) => entry.id === item.markerType)
                  : null;

                return (
                  <button
                    key={item.id}
                    type="button"
                    className={
                      "stratmap-placed-item " +
                      (selectedItemId === item.id ? "selected" : "") +
                      " " +
                      (item.kind === "marker" ? "marker" : "structure")
                    }
                    style={{
                      left: `${item.x}%`,
                      top: `${item.y}%`,
                      borderColor: structure?.colour || marker?.color || "#ffffff",
                      transform: `translate(-50%, -50%) rotate(${item.rotation}deg)`
                    }}
                    onClick={(event) => {
                      event.stopPropagation();
                      setSelectedItemId(item.id);
                    }}
                    title={structure?.label || marker?.label || "Placed Item"}
                  >
                    {item.kind === "marker" && marker?.path ? (
                      <img src={appAsset(marker.path)} alt={marker.label} draggable={false} />
                    ) : (
                      <span>{structure?.short || marker?.label.slice(0, 2) || "?"}</span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        </main>

        <aside className="stratmap-right">
          <Card>
            <h3>Structure Count</h3>

            <div className="stratmap-count-list">
              {structureCounts.map((structure) => (
                <div key={structure.id}>
                  <span>{structure.label}</span>
                  <b>{structure.count}</b>
                </div>
              ))}
            </div>
          </Card>

          <Card>
            <h3>Plan Notes</h3>

            <TextBox
              value={notes}
              onChange={setNotes}
              placeholder="Base plan, ARC defense, ammo placement, fallback points, bug-hole route..."
            />
          </Card>
        </aside>
      </div>
    </div>
  );
}

type Mi3DToolId =
  | "arc"
  | "mbu"
  | "wall"
  | "wallRamp"
  | "shortWall"
  | "largeDoor"
  | "smallDoor"
  | "bunker"
  | "tower"
  | "spotLight"
  | "electricFence"
  | "ammoCrate"
  | "fabricatorAmmo"
  | "fabricatorSpeed"
  | "fabricatorStims"
  | "fieldShower"
  | "refineryOre"
  | "refineryGas"
  | "stockPileAmmo"
  | "twinMG"
  | "sentryTurret";

type Mi3DPlacedItem = {
  id: string;
  toolId: Mi3DToolId;
  label: string;
  x: number;
  y?: number;
  z: number;
  rotationY: number;
};

type ActiveMi3DToolId = Mi3DToolId | null;

type Mi3DToolCategory =
  | "Building"
  | "Defense"
  | "Utility"
  | "Resource"
  | "Static"
  | "All";

type Mi3DTool = {
  id: Mi3DToolId;
  label: string;
  short: string;
  file: string;

  // visual model size
  targetSize: number;

  // placement footprint on the build grid
  buildFootprint?: number;

  placementMode?: "buildSquare" | "wallSquare" | "smallSquare" | "gateLine" | "fine";
  buildWidth?: number;
  buildDepth?: number;
  modelRotationOffset?: number;
  visualOffset?: [number, number, number];
  placementHeight?: number;

  color: number;
  cost: number;
  limit: number;
  category: Exclude<Mi3DToolCategory, "All">;
  yOffset?: number;

  blocksPlacement?: boolean;
  canOverlapStructures?: boolean;
  canShareBuildSquare?: boolean;
  canPlaceOnTerrain?: boolean;
};

const MI3D_BUILD_ZONE_SIZE = 120;
const MI3D_BUILD_ZONE_HALF = MI3D_BUILD_ZONE_SIZE / 2;
const MI3D_BUILD_ZONE_HEIGHT = 80;

// smaller squares
const MI3D_SUB_GRID_SIZE = 5;

// 1 build square = 4 smaller squares (2 x 2)
const MI3D_BUILD_GRID_SIZE = MI3D_SUB_GRID_SIZE * 2;
const MI3D_FINE_GRID_SIZE = MI3D_SUB_GRID_SIZE / 4;
const MI3D_SHORT_WALL_STEP = MI3D_BUILD_GRID_SIZE / 4;

type Mi3DZonePieceType = "buildZone" | "terrain" | "static";

type Mi3DPrimitiveShape =
  | "box"
  | "cylinder"
  | "ramp"
  | "rampCorner";

type Mi3DZonePiece = {
  id: string;
  type: Mi3DZonePieceType;
  label?: string;

  shape: Mi3DPrimitiveShape;
  file?: string;

  x: number;
  y?: number;
  z: number;

  width: number;
  depth: number;
  height: number;

  radiusTop?: number;
  radiusBottom?: number;
  radialSegments?: number;

  pivot?: [number, number, number];
  rotationY: number;

  color: number;
  grid: number;
};

