const MI3D_TOOL_ORDER: Mi3DToolId[] = [
  "arc",
  "mbu",

  "ammoCrate",
  "shortWall",
  "smallDoor",
  "wall",
  "wallRamp",
  "largeDoor",

  "spotLight",
  "tower",
  "bunker",
  "electricFence",

  "sentryTurret",
  "twinMG",


  "stockPileAmmo",
  "refineryOre",
  "refineryGas",

  "fabricatorAmmo",
  "fabricatorSpeed",
  "fabricatorStims",
  "fieldShower",
];

const getMi3DToolSortIndex = (id: Mi3DToolId) => {
  const index = MI3D_TOOL_ORDER.indexOf(id);
  return index === -1 ? 999 : index;
};

const getMi3DTool = (id: Mi3DToolId) =>
  mi3DTools.find((tool) => tool.id === id) || mi3DTools[0];

function addMi3DBox(
  group: THREE.Group,
  width: number,
  height: number,
  depth: number,
  color: number,
  x = 0,
  z = 0
) {
  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(width, height, depth),
    new THREE.MeshStandardMaterial({
      color,
      roughness: 0.7,
      metalness: 0.15
    })
  );

  mesh.position.set(x, height / 2, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  group.add(mesh);

  return mesh;
}

const MI3D_90_ROTATION_TOOLS: Mi3DToolId[] = [
  "wall",
  "wallRamp",
  "shortWall",
  "largeDoor",
  "smallDoor",
  "electricFence",
  "bunker",
  "arc",
  "mbu",
  "refineryOre",
  "refineryGas"
];

function getMi3DRotationStep(toolId: ActiveMi3DToolId) {
  if (!toolId) return 45;

  return MI3D_90_ROTATION_TOOLS.includes(toolId) ? 90 : 45;
}

const getMi3DBuildFootprint = (toolId: Mi3DToolId) => {
  const tool = getMi3DTool(toolId);

  return tool.buildFootprint ?? (
    tool.targetSize >= MI3D_BUILD_GRID_SIZE
      ? MI3D_BUILD_GRID_SIZE
      : MI3D_SUB_GRID_SIZE
  );
};

function snapMi3DToSquareCenter(value: number, squareSize: number) {
  const size = Math.max(squareSize, 1);

  return Math.floor(value / size) * size + size / 2;
}

function snapMi3DToNearestStep(value: number, step: number) {
  const size = Math.max(step, 0.01);
  return Math.round(value / size) * size;
}

function snapMi3DToBuildSquare(point: THREE.Vector3) {
  return {
    x: snapMi3DToSquareCenter(point.x, MI3D_BUILD_GRID_SIZE),
    z: snapMi3DToSquareCenter(point.z, MI3D_BUILD_GRID_SIZE)
  };
}

function snapMi3DToSmallSquare(point: THREE.Vector3) {
  return {
    x: snapMi3DToSquareCenter(point.x, MI3D_SUB_GRID_SIZE),
    z: snapMi3DToSquareCenter(point.z, MI3D_SUB_GRID_SIZE)
  };
}

function snapMi3DToFineGrid(point: THREE.Vector3) {
  return {
    x: snapMi3DToNearestStep(point.x, MI3D_FINE_GRID_SIZE),
    z: snapMi3DToNearestStep(point.z, MI3D_FINE_GRID_SIZE)
  };
}

function snapMi3DToNearestLine(value: number, gridSize: number) {
  const size = Math.max(gridSize, 1);

  return Math.round(value / size) * size;
}

function snapMi3DGateLinePoint(point: THREE.Vector3, rotationY: number) {
  const grid = MI3D_SUB_GRID_SIZE;

  // 0 / 180 degrees: gate runs left-right across a grid line.
  if (isMi3DRotationLengthwiseX(rotationY)) {
    return {
      x: snapMi3DToSquareCenter(point.x, grid),
      z: snapMi3DToNearestLine(point.z, grid)
    };
  }

  // 90 / 270 degrees: gate runs forward-back across a grid line.
  return {
    x: snapMi3DToNearestLine(point.x, grid),
    z: snapMi3DToSquareCenter(point.z, grid)
  };
}

function normaliseMi3DRotation(rotationY: number) {
  return ((rotationY % 360) + 360) % 360;
}

function isMi3DRotationLengthwiseX(rotationY: number) {
  const rotation = normaliseMi3DRotation(rotationY);

  return rotation === 0 || rotation === 180;
}

function getMi3DToolBuildSize(toolId: Mi3DToolId, rotationY: number) {
  const tool = getMi3DTool(toolId);

  const width = tool.buildWidth ?? tool.buildFootprint ?? MI3D_BUILD_GRID_SIZE;
  const depth = tool.buildDepth ?? tool.buildFootprint ?? MI3D_BUILD_GRID_SIZE;

  if (isMi3DRotationLengthwiseX(rotationY)) {
    return { width, depth };
  }

  return {
    width: depth,
    depth: width
  };
}

function snapMi3DWallLinePoint(point: THREE.Vector3, _rotationY: number) {
  const buildGrid = MI3D_BUILD_GRID_SIZE;

  return {
    x: snapMi3DToSquareCenter(point.x, buildGrid),
    z: snapMi3DToSquareCenter(point.z, buildGrid)
  };
}

function addMi3DCylinder(
  group: THREE.Group,
  radius: number,
  height: number,
  color: number,
  x = 0,
  z = 0
) {
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, height, 32),
    new THREE.MeshStandardMaterial({
      color,
      roughness: 0.7,
      metalness: 0.15
    })
  );

  mesh.position.set(x, height / 2, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  group.add(mesh);

  return mesh;
}

function cloneMi3DMaterial(material: THREE.Material | THREE.Material[]) {
  return Array.isArray(material)
    ? material.map((mat) => mat.clone())
    : material.clone();
}

function prepareMi3DModel(model: THREE.Object3D) {
  model.traverse((child) => {
    const mesh = child as THREE.Mesh;

    if (!mesh.isMesh) return;

    mesh.castShadow = true;
    mesh.receiveShadow = true;

    if (Array.isArray(mesh.material)) {
      mesh.material = mesh.material.map((material) => material.clone());
    } else if (mesh.material) {
      mesh.material = mesh.material.clone();
    }
  });
}

const MI3D_STRUCTURE_Y_OFFSET = 0;
// If structures sink too much, change to -0.8.
// If they are still too high, change to -1.6.

function normalizeMi3DModelToFloor(model: THREE.Object3D, targetSize: number) {
  model.updateMatrixWorld(true);

  const box = new THREE.Box3().setFromObject(model);
  const size = box.getSize(new THREE.Vector3());

  const largestXZ = Math.max(size.x, size.z) || 1;
  const scale = targetSize / largestXZ;

  model.scale.multiplyScalar(scale);
  model.updateMatrixWorld(true);

  const scaledBox = new THREE.Box3().setFromObject(model);
  const center = scaledBox.getCenter(new THREE.Vector3());

  // Only centre X/Z here.
  // Do NOT ground Y here because the parent object gets moved later.
  model.position.x -= center.x;
  model.position.z -= center.z;

  model.updateMatrixWorld(true);
}

function getMi3DVisibleMeshBox(object: THREE.Object3D) {
  const box = new THREE.Box3();
  let hasBox = false;

  object.updateMatrixWorld(true);

  object.traverse((child) => {
    const mesh = child as THREE.Mesh;

    if (!mesh.isMesh || !mesh.geometry || mesh.visible === false) return;

    const name = `${mesh.name || ""} ${mesh.parent?.name || ""}`.toLowerCase();

    // Ignore common helper/collider meshes if a GLB has them.
    if (
      name.includes("collision") ||
      name.includes("collider") ||
      name.includes("bounds") ||
      name.includes("socket")
    ) {
      return;
    }

    if (!mesh.geometry.boundingBox) {
      mesh.geometry.computeBoundingBox();
    }

    if (!mesh.geometry.boundingBox) return;

    const meshBox = mesh.geometry.boundingBox.clone();
    meshBox.applyMatrix4(mesh.matrixWorld);

    if (!hasBox) {
      box.copy(meshBox);
      hasBox = true;
    } else {
      box.union(meshBox);
    }
  });

  if (!hasBox) {
    box.setFromObject(object);
  }

  return box;
}

function groundMi3DObject(object: THREE.Object3D, floorY = 0) {
  object.updateMatrixWorld(true);

  const box = getMi3DVisibleMeshBox(object);
  const bottomY = box.min.y;

  object.position.y += floorY - bottomY + MI3D_STRUCTURE_Y_OFFSET;
  object.updateMatrixWorld(true);
}

function forceMi3DObjectToFloor(object: THREE.Object3D, floorY = 0) {
  object.updateMatrixWorld(true);

  const box = new THREE.Box3().setFromObject(object);
  const bottomY = box.min.y;

  object.position.y += floorY - bottomY;
  object.updateMatrixWorld(true);
}

function makeFallbackMi3DObject(toolId: Mi3DToolId) {
  const tool = getMi3DTool(toolId);

  const group = new THREE.Group();

  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(tool.targetSize, 2.5, tool.targetSize),
    new THREE.MeshStandardMaterial({
      color: 0x8b929c,
      roughness: 0.34,
      metalness: 0.68,
      emissive: 0x050607,
      emissiveIntensity: 0.05
    })
  );

  mesh.position.y = -1.25;
  mesh.castShadow = true;
  mesh.receiveShadow = true;

  group.add(mesh);
  group.name = tool.label;

  return group;
}

async function applyMi3DToolMaterial(
  model: THREE.Object3D,
  _tool: Mi3DTool
) {
  model.traverse((child) => {
    const mesh = child as THREE.Mesh;

    if (!mesh.isMesh) return;

    mesh.castShadow = true;
    mesh.receiveShadow = true;

    mesh.material = new THREE.MeshStandardMaterial({
      color: 0x8b929c,          // space grey
      roughness: 0.34,
      metalness: 0.68,
      emissive: 0x050607,
      emissiveIntensity: 0.05,
      side: THREE.DoubleSide
    });
  });
}

async function makeMi3DObjectFromGLB(
  loader: GLTFLoader,
  cache: Map<Mi3DToolId, THREE.Object3D>,
  toolId: Mi3DToolId
) {
  const tool = getMi3DTool(toolId);

  try {
    let template = cache.get(toolId);

    if (!template) {
      const gltf = await loader.loadAsync(appAsset(MI3D_MODEL_FOLDER + tool.file));
      template = gltf.scene;
      cache.set(toolId, template);
    }

    const group = new THREE.Group();
    const model = template.clone(true);

    prepareMi3DModel(model);
    await applyMi3DToolMaterial(model, tool);

    group.add(model);

    normalizeMi3DModelToFloor(model, tool.targetSize);

    const visualOffset = tool.visualOffset ?? [0, 0, 0];

    model.position.x += visualOffset[0];
    model.position.y += visualOffset[1] + (tool.yOffset ?? 0);
    model.position.z += visualOffset[2];

    group.name = tool.label;

    return group;
  } catch (error) {
    console.warn("Could not load GLB model:", tool.file, error);
    return makeFallbackMi3DObject(toolId);
  }
}

function disposeMi3DInstance(object: THREE.Object3D) {
  object.traverse((child) => {
    const mesh = child as THREE.Mesh;

    if (!mesh.isMesh) return;

    const material = mesh.material as THREE.Material | THREE.Material[] | undefined;

    if (Array.isArray(material)) {
      material.forEach((mat) => mat.dispose());
    } else if (material) {
      material.dispose();
    }
  });
}

function disposeMi3DObject(object: THREE.Object3D) {
  object.traverse((child) => {
    const mesh = child as THREE.Mesh;

    if (mesh.geometry) {
      mesh.geometry.dispose();
    }

    const material = mesh.material as THREE.Material | THREE.Material[] | undefined;

    if (Array.isArray(material)) {
      material.forEach((mat) => mat.dispose());
    } else if (material) {
      material.dispose();
    }
  });
}

function createMi3DGridLines(
  size: number,
  step: number,
  color: number,
  y: number,
  opacity = 1
) {
  const half = size / 2;
  const points: number[] = [];

  for (let pos = -half; pos <= half + 0.001; pos += step) {
    // horizontal line
    points.push(-half, y, pos, half, y, pos);

    // vertical line
    points.push(pos, y, -half, pos, y, half);
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(points, 3)
  );

  const material = new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity
  });

  return new THREE.LineSegments(geometry, material);
}

function createMi3DRampGeometry(width: number, height: number, depth: number) {
  const w = width / 2;
  const d = depth / 2;

  const vertices = new Float32Array([
    -w, 0, -d,
     w, 0, -d,
    -w, 0,  d,
     w, 0,  d,
    -w, height, d,
     w, height, d
  ]);

  const indices = [
    0, 1, 3, 0, 3, 2,
    2, 3, 5, 2, 5, 4,
    0, 2, 4, 0, 4, 1,
    1, 4, 5, 1, 5, 3,
    0, 4, 2,
    1, 3, 5
  ];

  const geometry = new THREE.BufferGeometry();

  geometry.setAttribute(
    "position",
    new THREE.BufferAttribute(vertices, 3)
  );

  geometry.setIndex(indices);
  geometry.computeVertexNormals();

  return geometry;
}

function createMi3DPrimitiveGeometry(piece: Mi3DZonePiece) {
  if (piece.shape === "cylinder") {
    return new THREE.CylinderGeometry(
      piece.radiusTop ?? piece.width / 2,
      piece.radiusBottom ?? piece.width / 2,
      piece.height,
      piece.radialSegments ?? 16
    );
  }

  if (piece.shape === "ramp" || piece.shape === "rampCorner") {
    return createMi3DRampGeometry(piece.width, piece.height, piece.depth);
  }

  return new THREE.BoxGeometry(piece.width, piece.height, piece.depth);
}

const mi3DZoneAssetLoader = new GLTFLoader();
const mi3DZoneAssetCache = new Map<string, THREE.Object3D>();

function createMi3DBuildZoneVisual(piece: Mi3DZonePiece) {
  const group = new THREE.Group();

  const pivot = piece.pivot ?? [0, 0, 0];
  const baseY = piece.y ?? 0;

  const width = piece.width;
  const depth = piece.depth;

  // Same height logic your normal zone pieces use.
  const visualY = baseY + piece.height / 2 + pivot[1] + 0.045;

  group.position.set(
    piece.x + pivot[0],
    visualY,
    piece.z + pivot[2]
  );

  group.rotation.y = THREE.MathUtils.degToRad(piece.rotationY);

  const fill = new THREE.Mesh(
    new THREE.PlaneGeometry(width, depth),
    new THREE.MeshBasicMaterial({
      color: 0x31ff9a,
      transparent: true,
      opacity: 0.36,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );

  fill.rotation.x = -Math.PI / 2;
  fill.renderOrder = 5;
  group.add(fill);

  const thinMaterial = new THREE.MeshBasicMaterial({
    color: 0x8dffd0,
    transparent: true,
    opacity: 0.75,
    depthWrite: false
  });

  const thickMaterial = new THREE.MeshBasicMaterial({
    color: 0x21ff9a,
    transparent: true,
    opacity: 0.95,
    depthWrite: false
  });

  const borderMaterial = new THREE.MeshBasicMaterial({
    color: 0x20ff9c,
    transparent: true,
    opacity: 1,
    depthWrite: false
  });

  const addXLine = (
    z: number,
    thickness: number,
    material: THREE.Material
  ) => {
    const line = new THREE.Mesh(
      new THREE.BoxGeometry(width, 0.035, thickness),
      material
    );

    line.position.set(0, 0.03, z);
    line.renderOrder = 6;
    group.add(line);
  };

  const addZLine = (
    x: number,
    thickness: number,
    material: THREE.Material
  ) => {
    const line = new THREE.Mesh(
      new THREE.BoxGeometry(thickness, 0.035, depth),
      material
    );

    line.position.set(x, 0.03, 0);
    line.renderOrder = 6;
    group.add(line);
  };

  // Thin smaller squares.
  const smallXStep = width / 4;
  const smallZStep = depth / 4;

  for (let x = -width / 2 + smallXStep; x < width / 2; x += smallXStep) {
    const isCenter = Math.abs(x) < 0.001;
    addZLine(x, isCenter ? 0.14 : 0.035, isCenter ? thickMaterial : thinMaterial);
  }

  for (let z = -depth / 2 + smallZStep; z < depth / 2; z += smallZStep) {
    const isCenter = Math.abs(z) < 0.001;
    addXLine(z, isCenter ? 0.14 : 0.035, isCenter ? thickMaterial : thinMaterial);
  }

  // Bright outside border.
  addXLine(-depth / 2, 0.18, borderMaterial);
  addXLine(depth / 2, 0.18, borderMaterial);
  addZLine(-width / 2, 0.18, borderMaterial);
  addZLine(width / 2, 0.18, borderMaterial);

  group.userData.zonePieceId = piece.id;
  group.userData.zonePieceType = piece.type;

  group.traverse((child) => {
    child.userData.zonePieceId = piece.id;
    child.userData.zonePieceType = piece.type;
  });

  return group;
}

function getRotatedZonePivot(
  pivot: [number, number, number],
  rotationY: number
) {
  const radians = THREE.MathUtils.degToRad(rotationY);
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);

  const x = pivot[0];
  const z = pivot[2];

  return {
    x: x * cos - z * sin,
    y: pivot[1],
    z: x * sin + z * cos
  };
}

async function createMi3DZonePieceObject(piece: Mi3DZonePiece) {
  if (piece.type === "buildZone") {
    return createMi3DBuildZoneVisual(piece);
  }

  const pivot = piece.pivot ?? [0, 0, 0];
  const rotatedPivot = getRotatedZonePivot(pivot, piece.rotationY);
  const baseY = piece.y ?? 0;

  if (piece.file) {
    let template = mi3DZoneAssetCache.get(piece.file);

    if (!template) {
      const gltf = await mi3DZoneAssetLoader.loadAsync(appAsset(piece.file));
      template = gltf.scene;
      mi3DZoneAssetCache.set(piece.file, template);
    }

    const object = template.clone(true);

    object.traverse((child) => {
      const mesh = child as THREE.Mesh;

      if (!mesh.isMesh) return;

      mesh.castShadow = piece.type !== "buildZone";
      mesh.receiveShadow = true;

      mesh.material = new THREE.MeshStandardMaterial({
        color: piece.color,
        transparent: piece.type === "buildZone",
        opacity: piece.type === "buildZone" ? 0.28 : 1,
        roughness: piece.type === "static" ? 0.38 : 0.65,
        metalness: piece.type === "static" ? 0.45 : 0.12,
        side: THREE.DoubleSide
      });
    });

    object.position.set(
      piece.x + rotatedPivot.x,
      baseY + piece.height / 2 + rotatedPivot.y + 0.03,
      piece.z + rotatedPivot.z
    );

    object.rotation.y = THREE.MathUtils.degToRad(piece.rotationY);
    object.userData.zonePieceId = piece.id;
    object.userData.zonePieceType = piece.type;

    return object;
  }

  const mesh = new THREE.Mesh(
    createMi3DPrimitiveGeometry(piece),
    new THREE.MeshStandardMaterial({
      color: piece.color,
      transparent: piece.type === "buildZone",
      opacity: piece.type === "buildZone" ? 0.28 : 1,
      roughness: piece.type === "static" ? 0.38 : 0.65,
      metalness: piece.type === "static" ? 0.45 : 0.12,
      side: THREE.DoubleSide
    })
  );

  mesh.position.set(
    piece.x + rotatedPivot.x,
    baseY + piece.height / 2 + rotatedPivot.y + 0.03,
    piece.z + rotatedPivot.z
  );

  mesh.rotation.y = THREE.MathUtils.degToRad(piece.rotationY);
  mesh.castShadow = piece.type !== "buildZone";
  mesh.receiveShadow = true;
  mesh.userData.zonePieceId = piece.id;
  mesh.userData.zonePieceType = piece.type;

  return mesh;
}

async function renderMi3DZonePieces(
  group: THREE.Group,
  pieces: Mi3DZonePiece[]
) {
  while (group.children.length > 0) {
    const child = group.children.pop();

    if (!child) continue;

    disposeMi3DObject(child);
  }

  for (const piece of pieces) {
    const object = await createMi3DZonePieceObject(piece);
    group.add(object);
  }
}

function createMi3DHardReferenceFloor(size = 240) {
  const group = new THREE.Group();

  // Main light grey floor

  const floor = new THREE.Mesh(
    new THREE.PlaneGeometry(size, size),
    new THREE.MeshStandardMaterial({
      color: 0x202225,       // light black / charcoal
      roughness: 0.82,
      metalness: 0.08,
      side: THREE.DoubleSide
    })
  );

  floor.rotation.x = -Math.PI / 2;
  floor.position.y = 0;
  floor.receiveShadow = true;
  floor.userData.isPlacementFloor = true;
  group.add(floor);

  // Thin solid base to make floor feel "hard"
  const floorBase = new THREE.Mesh(
    new THREE.BoxGeometry(size, 0.35, size),
    new THREE.MeshStandardMaterial({
      color: 0x111214,
      roughness: 0.9,
      metalness: 0.08
    })
  );

  floorBase.position.y = -0.2;
  floorBase.receiveShadow = true;
  group.add(floorBase);

  // Faint full-floor background grid
  const backgroundGrid = createMi3DGridLines(
    size,
    MI3D_SUB_GRID_SIZE,
    0x4f5a61,
    0.015,
    0.45
  );
  group.add(backgroundGrid);

const buildZoneLayer = new THREE.Group();
buildZoneLayer.name = "mi3d-editable-build-zone-layer";

void renderMi3DZonePieces(buildZoneLayer, activeMi3DZonePieces);

group.add(buildZoneLayer);

  return {
    group,
    raycastMesh: floor,
    buildZoneLayer
  };
}

function createMi3DWorkAreaLights(size = 240) {
  const group = new THREE.Group();

  const lightPositions: Array<[number, number, number, number, number]> = [
    [-size / 2 + 18, 18, -size / 2 + 18, 0x1eff00, 1.1],
    [size / 2 - 18, 18, -size / 2 + 18, 0xff7300, 1.0],
    [-size / 2 + 18, 18, size / 2 - 18, 0xff7300, 1.0],
    [size / 2 - 18, 18, size / 2 - 18, 0x1eff00, 1.1]
  ];

  lightPositions.forEach(([x, y, z, color, intensity]) => {
    const light = new THREE.PointLight(color, intensity, 115, 1.7);
    light.position.set(x, y, z);
    light.castShadow = false;
    group.add(light);

    const marker = new THREE.Mesh(
      new THREE.SphereGeometry(1.15, 16, 16),
      new THREE.MeshBasicMaterial({ color })
    );

    marker.position.set(x, 1.2, z);
    group.add(marker);
  });

  const overhead = new THREE.PointLight(0xffffff, 1.35, 260, 1.4);
  overhead.position.set(0, 65, 0);
  overhead.castShadow = false;
  group.add(overhead);

  return group;
}

function snapMi3DToGridEdge(value: number, gridSize: number, footprint: number) {
  const size = Math.max(gridSize, 1);
  const halfFootprint = footprint / 2;

  return Math.round((value - halfFootprint) / size) * size + halfFootprint;
}

function clampMi3DValue(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function getMi3DBuildZonePieceAtPoint(x: number, z: number) {
  return activeMi3DZonePieces.find((piece) => {
    if (piece.type !== "buildZone") return false;

    return isPointInsideRotatedZonePiece(x, z, piece);
  });
}

function getMi3DToolSnapStep(toolId: Mi3DToolId, piece: Mi3DZonePiece) {
  const tool = getMi3DTool(toolId);

  if (tool.id === "shortWall") {
    return MI3D_SHORT_WALL_STEP;
  }

  if (tool.placementMode === "fine") {
    return MI3D_FINE_GRID_SIZE;
  }

  if (
    tool.placementMode === "gateLine" ||
    tool.placementMode === "smallSquare"
  ) {
    return MI3D_SUB_GRID_SIZE;
  }

  if (
    tool.placementMode === "wallSquare" ||
    tool.placementMode === "buildSquare"
  ) {
    return MI3D_BUILD_GRID_SIZE;
  }

  return piece.grid || MI3D_BUILD_GRID_SIZE;
}

function snapMi3DPointToBuildZoneGrid(
  x: number,
  z: number,
  toolId: Mi3DToolId,
  rotationY = 0
) {
  const piece = getMi3DBuildZonePieceAtPoint(x, z);

  if (!piece) {
    const tool = getMi3DTool(toolId);
    const fallbackGrid = tool.buildFootprint || MI3D_BUILD_GRID_SIZE;

    return {
      x: snapMi3DToGridEdge(x, fallbackGrid, tool.buildFootprint || fallbackGrid),
      z: snapMi3DToGridEdge(z, fallbackGrid, tool.buildFootprint || fallbackGrid)
    };
  }

  const tool = getMi3DTool(toolId);
  const snapStep = getMi3DToolSnapStep(toolId, piece);
  const footprint = tool.buildFootprint || snapStep;
  const halfFootprint = footprint / 2;

  const angle = THREE.MathUtils.degToRad(-piece.rotationY);
  const dx = x - piece.x;
  const dz = z - piece.z;

  const localX = dx * Math.cos(angle) - dz * Math.sin(angle);
  const localZ = dx * Math.sin(angle) + dz * Math.cos(angle);

  const minX = -piece.width / 2 + halfFootprint;
  const maxX = piece.width / 2 - halfFootprint;
  const minZ = -piece.depth / 2 + halfFootprint;
  const maxZ = piece.depth / 2 - halfFootprint;

  const snappedLocalX = clampMi3DValue(
    Math.round((localX - minX) / snapStep) * snapStep + minX,
    minX,
    maxX
  );

  const snappedLocalZ = clampMi3DValue(
    Math.round((localZ - minZ) / snapStep) * snapStep + minZ,
    minZ,
    maxZ
  );

  const backAngle = THREE.MathUtils.degToRad(piece.rotationY);

  return {
    x:
      piece.x +
      snappedLocalX * Math.cos(backAngle) -
      snappedLocalZ * Math.sin(backAngle),

    z:
      piece.z +
      snappedLocalX * Math.sin(backAngle) +
      snappedLocalZ * Math.cos(backAngle)
  };
}

function snapMi3DLineToolToBuildZoneGrid(
  x: number,
  z: number,
  toolId: Mi3DToolId,
  rotationY = 0
) {
  const tool = getMi3DTool(toolId);
  const piece = getMi3DBuildZonePieceAtPoint(x, z);

  const length =
    tool.buildWidth ??
    tool.buildFootprint ??
    MI3D_BUILD_GRID_SIZE;

  const thickness = tool.buildDepth ?? 0.25;

  const gridStep = piece?.grid || MI3D_BUILD_GRID_SIZE;

  const alongStep =
    tool.id === "shortWall"
      ? MI3D_SHORT_WALL_STEP
      : gridStep;

  const lengthwiseX = isMi3DRotationLengthwiseX(rotationY);

  if (!piece) {
    const lineStep =
      tool.id === "shortWall"
        ? MI3D_SUB_GRID_SIZE
        : gridStep;

    const snapAlongLine = (value: number) => {
      const firstCentre = length / 2;

      return (
        Math.round((value - firstCentre) / alongStep) *
          alongStep +
        firstCentre
      );
    };

    const snapToLine = (value: number) => {
      return Math.round(value / lineStep) * lineStep;
    };

    if (lengthwiseX) {
      return {
        x: snapAlongLine(x),
        z: snapToLine(z)
      };
    }

    return {
      x: snapToLine(x),
      z: snapAlongLine(z)
    };
  }

  const angle = THREE.MathUtils.degToRad(-piece.rotationY);

  const dx = x - piece.x;
  const dz = z - piece.z;

  const localX =
    dx * Math.cos(angle) -
    dz * Math.sin(angle);

  const localZ =
    dx * Math.sin(angle) +
    dz * Math.cos(angle);

  const halfX = lengthwiseX
    ? length / 2
    : thickness / 2;

  const halfZ = lengthwiseX
    ? thickness / 2
    : length / 2;

  const minX = -piece.width / 2 + halfX;
  const maxX = piece.width / 2 - halfX;

  const minZ = -piece.depth / 2 + halfZ;
  const maxZ = piece.depth / 2 - halfZ;

  const snapAlongLine = (
    value: number,
    minimumEdge: number
  ) => {
    const firstCentre = minimumEdge + length / 2;

    return (
      Math.round(
        (value - firstCentre) / alongStep
      ) *
        alongStep +
      firstCentre
    );
  };

  const snapToGridLine = (
    value: number,
    minimumEdge: number
  ) => {
    return (
      Math.round(
        (value - minimumEdge) / gridStep
      ) *
        gridStep +
      minimumEdge
    );
  };

  const snappedLocalX = lengthwiseX
    ? clampMi3DValue(
        snapAlongLine(localX, -piece.width / 2),
        minX,
        maxX
      )
    : clampMi3DValue(
        snapToGridLine(localX, -piece.width / 2),
        minX,
        maxX
      );

  const snappedLocalZ = lengthwiseX
    ? clampMi3DValue(
        snapToGridLine(localZ, -piece.depth / 2),
        minZ,
        maxZ
      )
    : clampMi3DValue(
        snapAlongLine(localZ, -piece.depth / 2),
        minZ,
        maxZ
      );

  const backAngle =
    THREE.MathUtils.degToRad(piece.rotationY);

  return {
    x:
      piece.x +
      snappedLocalX * Math.cos(backAngle) -
      snappedLocalZ * Math.sin(backAngle),

    z:
      piece.z +
      snappedLocalX * Math.sin(backAngle) +
      snappedLocalZ * Math.cos(backAngle)
  };
}

function applyMi3DPreviewMaterial(object: THREE.Object3D) {
  object.traverse((child) => {
    const mesh = child as THREE.Mesh;

    if (!mesh.isMesh) return;

    mesh.castShadow = false;
    mesh.receiveShadow = false;

    mesh.material = new THREE.MeshStandardMaterial({
      color: 0x1eff00,
      emissive: 0x1eff00,
      emissiveIntensity: 0.25,
      transparent: true,
      opacity: 0.45,
      roughness: 0.6,
      metalness: 0.1,
      side: THREE.DoubleSide,
      depthWrite: false
    });
  });
}

type Mi3DPlacementResult = {
  valid: boolean;
  reason: string;
};

function getMi3DPlacementBox(
  toolId: Mi3DToolId,
  x: number,
  z: number,
  rotationY = 0
) {
  const { width, depth } = getMi3DToolBuildSize(toolId, rotationY);

  return new THREE.Box3(
    new THREE.Vector3(x - width / 2, -1, z - depth / 2),
    new THREE.Vector3(x + width / 2, MI3D_BUILD_ZONE_HEIGHT, z + depth / 2)
  );
}

function isPointInsideRotatedZonePiece(
  x: number,
  z: number,
  piece: Mi3DZonePiece
) {
  const angle = THREE.MathUtils.degToRad(-piece.rotationY);
  const dx = x - piece.x;
  const dz = z - piece.z;

  const localX = dx * Math.cos(angle) - dz * Math.sin(angle);
  const localZ = dx * Math.sin(angle) + dz * Math.cos(angle);

  return (
    localX >= -piece.width / 2 &&
    localX <= piece.width / 2 &&
    localZ >= -piece.depth / 2 &&
    localZ <= piece.depth / 2
  );
}

function isMi3DBoxInsideZonePiece(
  box: THREE.Box3,
  piece: Mi3DZonePiece
) {
  const corners = [
    { x: box.min.x, z: box.min.z },
    { x: box.min.x, z: box.max.z },
    { x: box.max.x, z: box.min.z },
    { x: box.max.x, z: box.max.z }
  ];

  return corners.every((corner) =>
    isPointInsideRotatedZonePiece(corner.x, corner.z, piece)
  );
}

function isMi3DInsideBuildZone(
  toolId: Mi3DToolId,
  x: number,
  z: number,
  rotationY = 0
) {
  const box = getMi3DPlacementBox(toolId, x, z, rotationY);

  const buildZonePieces = activeMi3DZonePieces.filter(
    (piece) => piece.type === "buildZone"
  );

  return buildZonePieces.some((piece) =>
    isMi3DBoxInsideZonePiece(box, piece)
  );
}

function doMi3DBoxesOverlap(
  a: THREE.Box3,
  b: THREE.Box3,
  gap = 0.05
) {
  return (
    a.min.x < b.max.x - gap &&
    a.max.x > b.min.x + gap &&
    a.min.z < b.max.z - gap &&
    a.max.z > b.min.z + gap
  );
}

function doesMi3DToolBlockPlacement(toolId: Mi3DToolId) {
  return getMi3DTool(toolId).blocksPlacement !== false;
}

function canMi3DToolOverlapStructures(toolId: Mi3DToolId) {
  return getMi3DTool(toolId).canOverlapStructures === true;
}

function canMi3DToolsShareBuildSquare(
  newToolId: Mi3DToolId,
  existingToolId: Mi3DToolId
) {
  const newTool = getMi3DTool(newToolId);
  const existingTool = getMi3DTool(existingToolId);

  // Fine / utility items can share with structures.
  if (newTool.canOverlapStructures || existingTool.canOverlapStructures) {
    return true;
  }

  // Allows multiple wall/gate/fence type items in the same build square.
  if (
    newTool.placementMode === "wallSquare" &&
    existingTool.placementMode === "wallSquare"
  ) {
    return true;
  }

  // Manual override for any tool you mark.
  if (newTool.canShareBuildSquare || existingTool.canShareBuildSquare) {
    return true;
  }

  return false;
}

function checkMi3DPlacement(
  toolId: Mi3DToolId,
  x: number,
  z: number,
  placedItems: Mi3DPlacedItem[],
  ignoreId = "",
  rotationY = 0,
  allowOutsideBuildZone = false
): Mi3DPlacementResult {
  if (!allowOutsideBuildZone && !isMi3DInsideBuildZone(toolId, x, z, rotationY)) {
    return {
      valid: false,
      reason: "Outside build zone"
    };
  }

  // Small items, ammo, fabricators, turrets, etc. can be placed
  // on/in/near existing structures.
  if (canMi3DToolOverlapStructures(toolId)) {
    return {
      valid: true,
      reason: "Valid placement"
    };
  }

  const newBox = getMi3DPlacementBox(toolId, x, z, rotationY);

  for (const item of placedItems) {
    if (item.id === ignoreId) continue;

    // Existing non-blocking items should not block placement either.
    if (!doesMi3DToolBlockPlacement(item.toolId)) continue;

    if (canMi3DToolsShareBuildSquare(toolId, item.toolId)) {
      continue;
    }

    const existingBox = getMi3DPlacementBox(
      item.toolId,
      item.x,
      item.z,
      item.rotationY
    );

    if (doMi3DBoxesOverlap(newBox, existingBox, 0.02)) {
      return {
        valid: false,
        reason: "Build zone occupied"
      };
    }
  }

  return {
    valid: true,
    reason: "Valid placement"
  };
}

function setMi3DPreviewValidity(
  object: THREE.Object3D,
  valid: boolean
) {
  const colour = valid ? 0x1eff00 : 0xff3333;
  const opacity = valid ? 0.45 : 0.62;

  object.traverse((child) => {
    const mesh = child as THREE.Mesh;

    if (!mesh.isMesh) return;

    const material = mesh.material as THREE.MeshStandardMaterial;

    if (!material) return;

    material.color.setHex(colour);
    material.emissive.setHex(colour);
    material.opacity = opacity;
    material.needsUpdate = true;
  });
}

const MI3D_PREVIEW_MODEL_CACHE = new Map<Mi3DToolId, THREE.Object3D>();

const MI3D_THUMB_CACHE = new Map<Mi3DToolId, string>();
const MI3D_THUMB_MODEL_CACHE = new Map<Mi3DToolId, THREE.Object3D>();

let mi3DThumbRenderer: THREE.WebGLRenderer | null = null;

async function makeMi3DToolThumbnail(toolId: Mi3DToolId) {
  const cached = MI3D_THUMB_CACHE.get(toolId);

  if (cached) {
    return cached;
  }

  if (!mi3DThumbRenderer) {
    mi3DThumbRenderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      preserveDrawingBuffer: true
    });

    mi3DThumbRenderer.setPixelRatio(1);
    mi3DThumbRenderer.setSize(160, 120);
    mi3DThumbRenderer.outputColorSpace = THREE.SRGBColorSpace;
    mi3DThumbRenderer.toneMapping = THREE.ACESFilmicToneMapping;
    mi3DThumbRenderer.toneMappingExposure = 1.35;
  }

  const renderer = mi3DThumbRenderer;

  const scene = new THREE.Scene();
  scene.background = null;

  const camera = new THREE.PerspectiveCamera(35, 160 / 120, 0.1, 500);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x333333, 1.7));

  const frontLight = new THREE.DirectionalLight(0xffffff, 2.2);
  frontLight.position.set(8, 10, 8);
  scene.add(frontLight);

  const sideLight = new THREE.DirectionalLight(0xffffff, 1.1);
  sideLight.position.set(-8, 5, -8);
  scene.add(sideLight);

  const loader = new GLTFLoader();

  const object = await makeMi3DObjectFromGLB(
    loader,
    MI3D_THUMB_MODEL_CACHE,
    toolId
  );

  scene.add(object);

  object.updateMatrixWorld(true);

  const box = new THREE.Box3().setFromObject(object);
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxSize = Math.max(size.x, size.y, size.z) || 1;

  object.position.x -= center.x;
  object.position.y -= center.y;
  object.position.z -= center.z;

  object.rotation.y = -Math.PI / 5;

  camera.position.set(maxSize * 1.25, maxSize * 0.75, maxSize * 1.45);
  camera.lookAt(0, 0, 0);

  renderer.clear();
  renderer.render(scene, camera);

  const url = renderer.domElement.toDataURL("image/png");

  scene.remove(object);
  disposeMi3DInstance(object);

  MI3D_THUMB_CACHE.set(toolId, url);

  return url;
}

function Mi3DStructurePreview(props: { toolId: Mi3DToolId }) {
  const tool = getMi3DTool(props.toolId);
  const [src, setSrc] = useState(() => MI3D_THUMB_CACHE.get(props.toolId) || "");

  useEffect(() => {
    let alive = true;

    setSrc(MI3D_THUMB_CACHE.get(props.toolId) || "");

    makeMi3DToolThumbnail(props.toolId)
      .then((url) => {
        if (alive) {
          setSrc(url);
        }
      })
      .catch((error) => {
        console.warn("Could not make structure thumbnail:", tool.label, error);
      });

    return () => {
      alive = false;
    };
  }, [props.toolId, tool.label]);

  return (
    <div className="mi3d-tool-preview-3d">
      {src ? (
        <img src={src} alt={tool.label} draggable={false} />
      ) : (
        <span>{tool.short || tool.label.slice(0, 4)}</span>
      )}
    </div>
  );
}

